steps.sampleSolution:
#include "raylib.h"

int main() {
    InitWindow(800, 450, "Arcade Nova-9");
    float x = 50.0f;
    while (!WindowShouldClose()) {
        x += 120.0f * GetFrameTime();
        BeginDrawing();
        ClearBackground(RAYWHITE);
        EndDrawing();
    }
    CloseWindow();
    return 0;
}
